// ============================================================
// AGENT #1 — ADS OPTIMIZER
// Phát hiện chiến dịch 'chảy máu': ROAS thấp, CPA đột biến
// Take Rate vượt ngưỡng, CP/DS tăng bất thường
// ============================================================

const sheetItems = $input.all();
const input = $('When Called by Main').first().json;
const projectConfigs = input.projectConfigs || [];

const col = (item, idx) => {
  const obj = item.json || item;
  return Object.values(obj)[idx];
};

const today = new Date();
const dayIdx = today.getDate();
// Columns: 0=Chỉ số, 1=Benchmark, 2=T01, 3=T02, 4=T03, 5=T04 MTD, 6=Apr1...
const dCol = 5 + dayIdx - 1; // yesterday
const d2Col = dCol - 1;       // 2 days ago
const d3Col = dCol - 2;       // 3 days ago

// Extract metrics
const m = {};
sheetItems.forEach(item => {
  const name = (col(item, 0) || '').toString().trim();
  if (!name || name.length < 2) return;
  m[name] = {
    mtd:   parseFloat(col(item, 5))  || 0,
    d1:    parseFloat(col(item, dCol))  || 0,
    d2:    parseFloat(col(item, d2Col)) || 0,
    d3:    parseFloat(col(item, d3Col)) || 0,
    bm:    (col(item, 1) || '').toString()
  };
});

// ---- BLEEDING DETECTION RULES ----
const alerts = [];

const pct = (a, b) => b !== 0 ? ((a - b) / Math.abs(b) * 100).toFixed(1) : 0;
const fmt = (n) => {
  n = parseFloat(n) || 0;
  if (Math.abs(n) >= 1e9) return (n/1e9).toFixed(2)+' tỷ';
  if (Math.abs(n) >= 1e6) return Math.round(n/1e6)+' tr';
  return n.toLocaleString('vi-VN');
};
const fmtPct = n => (parseFloat(n)*100).toFixed(1)+'%';

// Rule 1: Take Rate (Ads/DS) vượt ngưỡng 30%
const takeRate = m['Ads/DS (Take Rate)'];
if (takeRate && takeRate.d1 > 0.30) {
  alerts.push({
    severity: takeRate.d1 > 0.35 ? '🔴 NGHIÊM TRỌNG' : '🟡 CẢNH BÁO',
    metric: 'Take Rate (Ads/DS)',
    value: fmtPct(takeRate.d1),
    threshold: '≤ 30%',
    trend: `Hôm qua: ${fmtPct(takeRate.d1)} | T-2: ${fmtPct(takeRate.d2)} | T-3: ${fmtPct(takeRate.d3)}`,
    action: 'Giảm bid ngay trên TikTok Ads Manager. Review top campaigns theo CPA. Tắt ad sets có ROAS < 2.',
    owner: 'SaoBT + Lead Ads từng dự án'
  });
}

// Rule 2: CP/DS Livestream vượt ngưỡng 30%
const cpdsLive = m['CP/DS Live'];
if (cpdsLive && cpdsLive.d1 > 0.30) {
  const trend3days = [cpdsLive.d3, cpdsLive.d2, cpdsLive.d1];
  const increasing = trend3days.every((v, i) => i === 0 || v >= trend3days[i-1]);
  alerts.push({
    severity: increasing ? '🔴 NGHIÊM TRỌNG (3 ngày liên tiếp tăng)' : '🟡 CẢNH BÁO',
    metric: 'CP/DS Livestream',
    value: fmtPct(cpdsLive.d1),
    threshold: '≤ 30%',
    trend: `T-3→T-1: ${fmtPct(cpdsLive.d3)} → ${fmtPct(cpdsLive.d2)} → ${fmtPct(cpdsLive.d1)}`,
    action: 'Kiểm tra GPM, GMV/giờ livestream. Nếu GPM < 50K: đổi host hoặc tăng voucher. Review lịch live vs khung giờ peak.',
    owner: 'Lead Livestream + PM dự án'
  });
}

// Rule 3: GMV Ads giảm >20% so với hôm qua
const gmvAds = m['GMV Ads'];
if (gmvAds && gmvAds.d2 > 0) {
  const drop = parseFloat(pct(gmvAds.d1, gmvAds.d2));
  if (drop < -20) {
    alerts.push({
      severity: drop < -35 ? '🔴 NGHIÊM TRỌNG' : '🟡 CẢNH BÁO',
      metric: 'GMV Ads',
      value: fmt(gmvAds.d1),
      prev: fmt(gmvAds.d2),
      change: drop.toFixed(1)+'%',
      threshold: 'Giảm > 20% so với ngày trước',
      action: 'Check ngân sách ads có hết không. Kiểm tra quality score creative. Review audience overlap. Xem CPM có tăng đột biến không.',
      owner: 'SaoBT'
    });
  }
}

// Rule 4: Chi phí Ads tăng >25% nhưng GMV không tăng tương ứng
const chiPhiAds = m['Chi phí quảng cáo Ads'];
if (chiPhiAds && gmvAds && chiPhiAds.d2 > 0 && gmvAds.d2 > 0) {
  const costChange = parseFloat(pct(chiPhiAds.d1, chiPhiAds.d2));
  const gmvChange  = parseFloat(pct(gmvAds.d1, gmvAds.d2));
  if (costChange > 25 && gmvChange < costChange - 15) {
    alerts.push({
      severity: '🔴 CHẢY MÁU',
      metric: 'Chi phí Ads tăng mạnh, GMV không theo',
      costChange: '+' + costChange.toFixed(1)+'%',
      gmvChange: gmvChange.toFixed(1)+'%',
      action: 'Pause ngay các campaign có ROAS thấp nhất. Giữ budget cho top 20% campaign hiệu quả nhất. Report chi tiết theo campaign level.',
      owner: 'SaoBT — BÁO CÁO TRONG 2 GIỜ'
    });
  }
}

// Rule 5: Net Profit Margin âm
const npm = m['Net Profit Margin'];
if (npm && npm.d1 < 0) {
  alerts.push({
    severity: '🔴 KHẨN CẤP — THUA LỖ',
    metric: 'Net Profit Margin',
    value: fmtPct(npm.d1),
    action: 'Dừng scale ngay. Review P&L theo từng kênh. Tạm giảm 30% ngân sách ads đến khi margin dương.',
    owner: 'CEO + SaoBT'
  });
}

// Rule 6: Tỷ lệ hủy đơn > 15%
const huyDon = m['Tỷ lệ hủy đơn'];
if (huyDon && huyDon.d1 > 0.15) {
  alerts.push({
    severity: huyDon.d1 > 0.20 ? '🔴 NGHIÊM TRỌNG' : '🟡 CẢNH BÁO',
    metric: 'Tỷ lệ hủy đơn',
    value: fmtPct(huyDon.d1),
    threshold: '≤ 15%',
    action: 'Kiểm tra lý do hủy (hết hàng? giao hàng chậm? giá không match?). Check stock tồn kho. Review landing page CVR.',
    owner: 'Lead Vận hành'
  });
}

// Summary stats
const summaryStats = {
  takeRate:       takeRate  ? fmtPct(takeRate.d1)  : 'N/A',
  cpdsLive:       cpdsLive  ? fmtPct(cpdsLive.d1)  : 'N/A',
  gmvAds_ytd:     gmvAds    ? fmt(gmvAds.d1)        : 'N/A',
  chiPhiAds_ytd:  chiPhiAds ? fmt(chiPhiAds.d1)     : 'N/A',
  netProfitMargin: npm       ? fmtPct(npm.d1)        : 'N/A',
  huyDon:         huyDon    ? fmtPct(huyDon.d1)     : 'N/A'
};

const criticalAlerts = alerts.filter(a => a.severity.includes('🔴'));
const warningAlerts  = alerts.filter(a => a.severity.includes('🟡'));

// Build Claude request
const systemPrompt = `Bạn là AI Ads Optimizer của Hecatech — chuyên phát hiện và xử lý chiến dịch ads đang 'chảy máu'.
Nhiệm vụ: Phân tích các cảnh báo và tạo alert message cụ thể, có thể hành động ngay.
Viết tiếng Việt. Súc tích. Số liệu thực tế. Ưu tiên critical trước.`;

const today_str = today.toLocaleDateString('vi-VN');
const userPrompt = `DAILY ADS OPTIMIZER REPORT — ${today_str}

KẾT QUẢ PHÂN TÍCH:
${JSON.stringify({ criticalAlerts, warningAlerts, summaryStats }, null, 2)}

Tạo Ads Alert Message theo format:

🚨 ADS OPTIMIZER ALERT — ${today_str}

[Nếu có critical alerts]
🔴 HÀNH ĐỘNG NGAY (trong 2 giờ):
[Mỗi alert: metric + số liệu thực + nguyên nhân có thể + hành động cụ thể + owner]

[Nếu có warning alerts]
🟡 THEO DÕI HÔM NAY:
[Tóm tắt ngắn]

📊 KHỬ BỠI NHANH:
• Take Rate: [giá trị] | CP/DS Live: [giá trị] | Hủy đơn: [giá trị]

[Nếu không có alert nào]
✅ Ads đang trong ngưỡng an toàn — không có cảnh báo.

Dưới 280 từ.`;

return [{
  json: {
    projectConfigs,
    alerts,
    hasCritical: criticalAlerts.length > 0,
    hasAlerts: alerts.length > 0,
    summaryStats,
    claudeRequest: {
      model: 'claude-sonnet-4-6',
      max_tokens: 800,
      system: systemPrompt,
      messages: [{ role: 'user', content: userPrompt }]
    }
  }
}];

// Critical: send to BOTH CEO group AND Ads group
const alertText = $input.first().json?.content?.[0]?.text || '⚠️ Lỗi phân tích Ads.';
const larkMsg = { msg_type: 'text', content: { text: alertText } };
return [
  { json: { url: $vars.LARK_CEO_WEBHOOK_URL,  larkMessage: larkMsg } },
  { json: { url: $vars.LARK_ADS_WEBHOOK_URL,  larkMessage: larkMsg } }
];
